import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { API_URL, testConnection } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [originalImage, setOriginalImage] = useState(null);
  const [processedImage, setProcessedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [accuracy, setAccuracy] = useState(null);
  const [serverConnected, setServerConnected] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    const check = async () => {
      const r = await testConnection();
      setServerConnected(r.success);
      if (!r.success) setError(r.error);
    };
    check();
  }, []);

  const handleFileSelect = e => {
    const f = e.target.files[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = ev => {
      setOriginalImage(ev.target.result);
      setProcessedImage(null);
      setAccuracy(null);
      setError(null);
    };
    r.readAsDataURL(f);
  };

  const processImage = async () => {
    if (!originalImage) return;
    setLoading(true);
    setError(null);
    try {
      const res = await fetch(originalImage);
      const blob = await res.blob();
      const fd = new FormData();
      fd.append('image', blob, 'image.png');
      fd.append('colorblind_type', colorblindType);
      fd.append('mode', mode);

      const r = await axios.post(`${API_URL}/process-image`, fd);
      setProcessedImage(`data:image/png;base64,${r.data.processed_image}`);
      setAccuracy(r.data.accuracy);
    } catch {
      setError('Processing failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="component-container">
      <h2>Image Processor</h2>

      <div className="upload-area" onClick={() => fileInputRef.current.click()}>
        <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileSelect} />
        <p>Click or drag and drop an image here</p>
      </div>

      {error && <div className="error">{error}</div>}

      {(originalImage || processedImage) && (
        <div className="image-preview">
          {originalImage && <img src={originalImage} alt="Original" />}
          {processedImage && (
            <div>
              <img src={processedImage} alt="Processed" />
              <p>Filter Accuracy: {accuracy}%</p>
            </div>
          )}
        </div>
      )}

      <button onClick={processImage} disabled={!originalImage || loading}>
        {loading ? 'Processing...' : 'Process Image'}
      </button>
    </div>
  );
};

export default ImageProcessor;
